package com.triathlon.prep.core;
import java.io.*;import java.util.*;import java.util.zip.*;
/** Two public draft versions in one atomic snapshot. No credentials or execution flags on disk. */
public final class FileDeviceConfigStore {
 private static final int MAGIC=0x44434631;private final File file,pending,backup;
 public static final class Snapshot {public final DeviceConfigDraft current,previous;public final long revision;Snapshot(DeviceConfigDraft current,DeviceConfigDraft previous,long revision){this.current=current;this.previous=previous;this.revision=revision;}}
 public FileDeviceConfigStore(File directory)throws IOException{if(directory==null||!directory.exists()&&!directory.mkdirs()||!directory.isDirectory())throw new IOException("Private public-draft store unavailable");file=new File(directory,"device-config.bin");pending=new File(directory,"device-config.bin.new");backup=new File(directory,"device-config.bin.bak");}
 public synchronized Snapshot load()throws IOException{recover();if(!file.exists())return new Snapshot(DeviceConfigDraft.empty(),null,0);if(!file.isFile()||file.length()>65536)throw new IOException("Invalid public configuration snapshot");CRC32 crc=new CRC32();try(DataInputStream in=new DataInputStream(new CheckedInputStream(new FileInputStream(file),crc))){if(in.readInt()!=MAGIC||in.readInt()!=1)throw new IOException("Unsupported configuration version");long revision=in.readLong();if(revision<1)throw new IOException("Invalid configuration revision");DeviceConfigDraft current=read(in),previous=in.readBoolean()?read(in):null;long checksum=crc.getValue();if(in.readLong()!=checksum||in.read()!=-1)throw new IOException("Configuration checksum mismatch");return new Snapshot(current,previous,revision);}catch(IllegalArgumentException e){throw new IOException("Invalid public configuration",e);}}
 public synchronized Snapshot save(DeviceConfigDraft draft,long expectedRevision)throws IOException{if(draft==null||!draft.review().validForSave)throw new IOException("Invalid public draft");Snapshot old=load();if(old.revision!=expectedRevision||old.revision==Long.MAX_VALUE)throw new IOException("Stale configuration revision");Snapshot saved=new Snapshot(draft,old.current,old.revision+1);persist(saved);return saved;}
 public synchronized Snapshot rollback(long expectedRevision)throws IOException{Snapshot current=load();if(current.revision!=expectedRevision||current.previous==null)throw new IOException("No matching rollback version");return save(current.previous,expectedRevision);}
 private DeviceConfigDraft read(DataInputStream in)throws IOException{int count=in.readInt();if(count<0||count>DeviceConfigDraft.Field.values().length)throw new IOException("Invalid public field count");Map<String,String> values=new LinkedHashMap<>();for(int i=0;i<count;i++){String key=in.readUTF(),value=in.readUTF();if(values.put(key,value)!=null)throw new IOException("Duplicate public field");}DeviceConfigDraft result=DeviceConfigDraft.from(values);if(!result.review().validForSave)throw new IOException("Unsafe public parameters");return result;}
 private void write(DataOutputStream out,DeviceConfigDraft draft)throws IOException{Map<String,String> values=draft.toMap();out.writeInt(values.size());for(Map.Entry<String,String> e:values.entrySet()){out.writeUTF(e.getKey());out.writeUTF(e.getValue());}}
 private void persist(Snapshot value)throws IOException{CRC32 crc=new CRC32();try(FileOutputStream stream=new FileOutputStream(pending);DataOutputStream out=new DataOutputStream(new CheckedOutputStream(stream,crc))){out.writeInt(MAGIC);out.writeInt(1);out.writeLong(value.revision);write(out,value.current);out.writeBoolean(value.previous!=null);if(value.previous!=null)write(out,value.previous);out.writeLong(crc.getValue());out.flush();stream.getFD().sync();}if(file.exists()&&!file.renameTo(backup))throw new IOException("Cannot preserve configuration");if(!pending.renameTo(file)){if(backup.exists())backup.renameTo(file);throw new IOException("Cannot replace configuration");}if(backup.exists()&&!backup.delete())throw new IOException("Configuration cleanup unconfirmed");}
 private void recover()throws IOException{if(backup.exists()){if(file.exists()&&!file.delete()||!backup.renameTo(file))throw new IOException("Cannot recover public configuration");}if(pending.exists()&&!pending.delete())throw new IOException("Cannot discard interrupted draft");}
}
